import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第一册：英语初阶 · 全册易错点 · 第106–131课","description":"逐课检查常见错误、适用边界和正确表达。","frontmatter":{"title":"第一册：英语初阶 · 全册易错点 · 第106–131课","description":"逐课检查常见错误、适用边界和正确表达。","splitFrom":"life/english/new-concept/book-1/mistakes.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 全册易错点","summary":"逐课检查常见错误、适用边界和正确表达。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 全册易错点 · 第80–105课","link":"/life/english/new-concept/book-1/mistakes-part-04"},"next":{"text":"第一册：英语初阶 · 全册易错点 · 第132–144课","link":"/life/english/new-concept/book-1/mistakes-part-06"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 全册易错点 · 第80–105课","link":"/life/english/new-concept/book-1/mistakes-part-04"},"next":{"text":"第一册：英语初阶 · 全册易错点 · 第132–144课","link":"/life/english/new-concept/book-1/mistakes-part-06"}},"headers":[],"relativePath":"life/english/new-concept/book-1/mistakes-part-05.md","filePath":"life/english/new-concept/book-1/mistakes-part-05.md"}'),s={name:"life/english/new-concept/book-1/mistakes-part-05.md"};function i(r,e,h,l,p,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第一册-英语初阶-·-全册易错点-·-第106–131课" tabindex="-1">第一册：英语初阶 · 全册易错点 · 第106–131课 <a class="header-anchor" href="#第一册-英语初阶-·-全册易错点-·-第106–131课" aria-label="Permalink to &quot;第一册：英语初阶 · 全册易错点 · 第106–131课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/mistakes">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><h2 id="l106-·-动词-宾语-to-do" tabindex="-1">L106 · 动词 + 宾语 + to do <a class="header-anchor" href="#l106-·-动词-宾语-to-do" aria-label="Permalink to &quot;L106 · 动词 + 宾语 + to do {#l106-·-动词-宾语-to-do}&quot;">​</a></h2><p>tell her not to send 与 tell her to not send 相比，本课采用常见的 not to；不要用 tell she。</p><p><strong>对照例句：</strong> I told her not to send the draft yet.</p><p>Told 为过去式，her 为宾语；not to send 是否定不定式，yet 表暂时仍不要发送。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-106">回看讲解和练习</a></p><h2 id="l107-·-形容词比较级" tabindex="-1">L107 · 形容词比较级 <a class="header-anchor" href="#l107-·-形容词比较级" aria-label="Permalink to &quot;L107 · 形容词比较级 {#l107-·-形容词比较级}&quot;">​</a></h2><p>不能写 more lighter；lighter 本身已经是比较级。</p><p><strong>对照例句：</strong> This backpack is lighter than that one.</p><p>Lighter 是 light 的比较级；than that one 引出同类比较对象，one 替代 backpack。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-107">回看讲解和练习</a></p><h2 id="l108-·-形容词比较级" tabindex="-1">L108 · 形容词比较级 <a class="header-anchor" href="#l108-·-形容词比较级" aria-label="Permalink to &quot;L108 · 形容词比较级 {#l108-·-形容词比较级}&quot;">​</a></h2><p>不能写 more lighter；lighter 本身已经是比较级。</p><p><strong>对照例句：</strong> The blue jacket is more expensive than the grey one.</p><p>More expensive 是多音节形容词比较级；the grey one 替代 the grey jacket，避免重复名词。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-108">回看讲解和练习</a></p><h2 id="l109-·-much-many-的比较级" tabindex="-1">L109 · much/many 的比较级 <a class="header-anchor" href="#l109-·-much-many-的比较级" aria-label="Permalink to &quot;L109 · much/many 的比较级 {#l109-·-much-many-的比较级}&quot;">​</a></h2><p>标准书面表达中，cups 可数复数用 fewer；sugar 不可数用 less。</p><p><strong>对照例句：</strong> This recipe needs less sugar than the old one.</p><p>Needs 与单数主语 this recipe 一致；less 修饰不可数 sugar，than the old one 比较两个配方。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-109">回看讲解和练习</a></p><h2 id="l110-·-much-many-的比较级" tabindex="-1">L110 · much/many 的比较级 <a class="header-anchor" href="#l110-·-much-many-的比较级" aria-label="Permalink to &quot;L110 · much/many 的比较级 {#l110-·-much-many-的比较级}&quot;">​</a></h2><p>标准书面表达中，cups 可数复数用 fewer；sugar 不可数用 less。</p><p><strong>对照例句：</strong> We used fewer paper cups this week.</p><p>Used 为过去式，fewer 修饰复数可数名词 paper cups；this week 在这里指本周已发生的用杯情况。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-110">回看讲解和练习</a></p><h2 id="l111-·-形容词最高级" tabindex="-1">L111 · 形容词最高级 <a class="header-anchor" href="#l111-·-形容词最高级" aria-label="Permalink to &quot;L111 · 形容词最高级 {#l111-·-形容词最高级}&quot;">​</a></h2><p>通常最高级前有 the；不能写 the most lightest。</p><p><strong>对照例句：</strong> This is the lightest laptop in the shop.</p><p>The lightest 为最高级，in the shop 限定比较范围；laptop 是被选中的类别名词。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-111">回看讲解和练习</a></p><h2 id="l112-·-形容词最高级" tabindex="-1">L112 · 形容词最高级 <a class="header-anchor" href="#l112-·-形容词最高级" aria-label="Permalink to &quot;L112 · 形容词最高级 {#l112-·-形容词最高级}&quot;">​</a></h2><p>通常最高级前有 the；不能写 the most lightest。</p><p><strong>对照例句：</strong> Of the three routes, this one is the most convenient.</p><p>Of the three routes 提供三者范围；the most convenient 是多音节形容词最高级，one 指路线。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-112">回看讲解和练习</a></p><h2 id="l113-·-so-neither-简短附和" tabindex="-1">L113 · so/neither 简短附和 <a class="header-anchor" href="#l113-·-so-neither-简短附和" aria-label="Permalink to &quot;L113 · so/neither 简短附和 {#l113-·-so-neither-简短附和}&quot;">​</a></h2><p>原句含 can，附和保留 can；不要回答 Neither am I 来对应 cannot skate。</p><p><strong>对照例句：</strong> I enjoy hiking, and so does my sister.</p><p>第一分句 enjoy 为一般现在时；附和中的主语 my sister 为单数，因此用 so does，而不是 so do。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-113">回看讲解和练习</a></p><h2 id="l114-·-so-neither-简短附和" tabindex="-1">L114 · so/neither 简短附和 <a class="header-anchor" href="#l114-·-so-neither-简短附和" aria-label="Permalink to &quot;L114 · so/neither 简短附和 {#l114-·-so-neither-简短附和}&quot;">​</a></h2><p>原句含 can，附和保留 can；不要回答 Neither am I 来对应 cannot skate。</p><p><strong>对照例句：</strong> I cannot skate, and neither can Tom.</p><p>Cannot skate 是否定能力陈述；neither can Tom 用相同情态动词并倒装，表示汤姆也不能。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-114">回看讲解和练习</a></p><h2 id="l115-·-复合不定代词" tabindex="-1">L115 · 复合不定代词 <a class="header-anchor" href="#l115-·-复合不定代词" aria-label="Permalink to &quot;L115 · 复合不定代词 {#l115-·-复合不定代词}&quot;">​</a></h2><p>不要写 someone are；也不要用 not nothing 表达普通的“没有什么”。</p><p><strong>对照例句：</strong> Someone is waiting at the side door.</p><p>Someone 作主语按单数处理，因此用 is waiting；at the side door 表等候位置。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-115">回看讲解和练习</a></p><h2 id="l116-·-复合不定代词" tabindex="-1">L116 · 复合不定代词 <a class="header-anchor" href="#l116-·-复合不定代词" aria-label="Permalink to &quot;L116 · 复合不定代词 {#l116-·-复合不定代词}&quot;">​</a></h2><p>不要写 someone are；也不要用 not nothing 表达普通的“没有什么”。</p><p><strong>对照例句：</strong> There is nothing unusual in the box.</p><p>There is 引出 nothing；unusual 放在复合不定代词之后，nothing 已含否定，无需再加 not。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-116">回看讲解和练习</a></p><h2 id="l117-·-过去进行时" tabindex="-1">L117 · 过去进行时 <a class="header-anchor" href="#l117-·-过去进行时" aria-label="Permalink to &quot;L117 · 过去进行时 {#l117-·-过去进行时}&quot;">​</a></h2><p>过去背景用 was/were，不用现在的 am/is/are；短事件不一定也要写进行时。</p><p><strong>对照例句：</strong> I was making breakfast when the lights went out.</p><p>Was making 描写过去背景动作；when 引出的 went out 表停电事件。两者形成持续背景与突发事件的对照。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-117">回看讲解和练习</a></p><h2 id="l118-·-过去进行时" tabindex="-1">L118 · 过去进行时 <a class="header-anchor" href="#l118-·-过去进行时" aria-label="Permalink to &quot;L118 · 过去进行时 {#l118-·-过去进行时}&quot;">​</a></h2><p>过去背景用 was/were，不用现在的 am/is/are；短事件不一定也要写进行时。</p><p><strong>对照例句：</strong> They were waiting outside at eight yesterday.</p><p>Were waiting 与复数主语 they 一致；at eight yesterday 指过去特定时刻，说明那个时刻正在等。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-118">回看讲解和练习</a></p><h2 id="l119-·-过去完成时" tabindex="-1">L119 · 过去完成时 <a class="header-anchor" href="#l119-·-过去完成时" aria-label="Permalink to &quot;L119 · 过去完成时 {#l119-·-过去完成时}&quot;">​</a></h2><p>过去完成时必须相对于过去参照点；不要只因 yesterday 就任意加 had。</p><p><strong>对照例句：</strong> By the time we arrived, the museum had closed.</p><p>We arrived 给出过去参照点；had closed 表博物馆关门发生得更早。by the time 强调到达时已有结果。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-119">回看讲解和练习</a></p><h2 id="l120-·-过去完成时" tabindex="-1">L120 · 过去完成时 <a class="header-anchor" href="#l120-·-过去完成时" aria-label="Permalink to &quot;L120 · 过去完成时 {#l120-·-过去完成时}&quot;">​</a></h2><p>过去完成时必须相对于过去参照点；不要只因 yesterday 就任意加 had。</p><p><strong>对照例句：</strong> She had saved the file before the computer stopped.</p><p>Had saved 表先完成保存，stopped 表随后电脑停止；before 显式说明事件顺序。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-120">回看讲解和练习</a></p><h2 id="l121-·-关系代词作主语" tabindex="-1">L121 · 关系代词作主语 <a class="header-anchor" href="#l121-·-关系代词作主语" aria-label="Permalink to &quot;L121 · 关系代词作主语 {#l121-·-关系代词作主语}&quot;">​</a></h2><p>不能写 the woman who she lives upstairs；who 已经是从句主语。</p><p><strong>对照例句：</strong> The woman who lives upstairs is a violinist.</p><p>The woman 是先行词，who 在从句中作 lives 的主语，不能省略；主句谓语为 is。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-121">回看讲解和练习</a></p><h2 id="l122-·-关系代词作主语" tabindex="-1">L122 · 关系代词作主语 <a class="header-anchor" href="#l122-·-关系代词作主语" aria-label="Permalink to &quot;L122 · 关系代词作主语 {#l122-·-关系代词作主语}&quot;">​</a></h2><p>不能写 the woman who she lives upstairs；who 已经是从句主语。</p><p><strong>对照例句：</strong> The lamp that stands by the sofa is broken.</p><p>The lamp 是先行词，that 作 stands 的主语；by the sofa 是从句内位置说明，主句 is broken 说明状态。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-122">回看讲解和练习</a></p><h2 id="l123-·-关系代词作宾语" tabindex="-1">L123 · 关系代词作宾语 <a class="header-anchor" href="#l123-·-关系代词作宾语" aria-label="Permalink to &quot;L123 · 关系代词作宾语 {#l123-·-关系代词作宾语}&quot;">​</a></h2><p>met 后不再补 him；先行词 guide 已通过关系从句充当 met 的宾语。</p><p><strong>对照例句：</strong> The guide we met in Perth spoke three languages.</p><p>The guide 是先行词；we met 中 we 为主语，被省略的关系代词是 met 的宾语；spoke 是主句谓语。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-123">回看讲解和练习</a></p><h2 id="l124-·-关系代词作宾语" tabindex="-1">L124 · 关系代词作宾语 <a class="header-anchor" href="#l124-·-关系代词作宾语" aria-label="Permalink to &quot;L124 · 关系代词作宾语 {#l124-·-关系代词作宾语}&quot;">​</a></h2><p>met 后不再补 him；先行词 guide 已通过关系从句充当 met 的宾语。</p><p><strong>对照例句：</strong> This is the photograph that I took at the harbour.</p><p>That 在从句 I took 中作宾语，可在这一限制性从句中省略；at the harbour 表拍照地点。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-124">回看讲解和练习</a></p><h2 id="l125-·-have-to-的时态与否定" tabindex="-1">L125 · have to 的时态与否定 <a class="header-anchor" href="#l125-·-have-to-的时态与否定" aria-label="Permalink to &quot;L125 · have to 的时态与否定 {#l125-·-have-to-的时态与否定}&quot;">​</a></h2><p>doesn&#39;t 后接 have to 而非 has to；否定 have to 表不必。</p><p><strong>对照例句：</strong> I had to water the plants before work.</p><p>Had to 是过去的客观必要，后接原形 water；plants 是宾语，before work 表发生时间。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-125">回看讲解和练习</a></p><h2 id="l126-·-have-to-的时态与否定" tabindex="-1">L126 · have to 的时态与否定 <a class="header-anchor" href="#l126-·-have-to-的时态与否定" aria-label="Permalink to &quot;L126 · have to 的时态与否定 {#l126-·-have-to-的时态与否定}&quot;">​</a></h2><p>doesn&#39;t 后接 have to 而非 has to；否定 have to 表不必。</p><p><strong>对照例句：</strong> She does not have to work this Sunday.</p><p>Does not have to 表第三人称单数的“不必”；have 恢复原形，this Sunday 指本次星期日。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-126">回看讲解和练习</a></p><h2 id="l127-·-must-cannot-表现在推断" tabindex="-1">L127 · must/cannot 表现在推断 <a class="header-anchor" href="#l127-·-must-cannot-表现在推断" aria-label="Permalink to &quot;L127 · must/cannot 表现在推断 {#l127-·-must-cannot-表现在推断}&quot;">​</a></h2><p>mustn&#39;t be 表禁止时不等于不可能；推断不可能常用 can&#39;t be。</p><p><strong>对照例句：</strong> The office lights are on; someone must be inside.</p><p>前半句灯亮着是观察线索；后半句 must be 是强推断，someone 是主语，inside 为地点表语。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-127">回看讲解和练习</a></p><h2 id="l128-·-must-cannot-表现在推断" tabindex="-1">L128 · must/cannot 表现在推断 <a class="header-anchor" href="#l128-·-must-cannot-表现在推断" aria-label="Permalink to &quot;L128 · must/cannot 表现在推断 {#l128-·-must-cannot-表现在推断}&quot;">​</a></h2><p>mustn&#39;t be 表禁止时不等于不可能；推断不可能常用 can&#39;t be。</p><p><strong>对照例句：</strong> That cannot be our bus; it has a different number.</p><p>Cannot be 表不可能是；分号后 different number 提供推断依据，its number 与 expected bus number 不同。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-128">回看讲解和练习</a></p><h2 id="l129-·-情态动词-have-done" tabindex="-1">L129 · 情态动词 + have done <a class="header-anchor" href="#l129-·-情态动词-have-done" aria-label="Permalink to &quot;L129 · 情态动词 + have done {#l129-·-情态动词-have-done}&quot;">​</a></h2><p>must have rained 是推测，不能写 must had rained；情态动词后保留 have 原形。</p><p><strong>对照例句：</strong> The road is wet; it must have rained overnight.</p><p>The road is wet 是现在证据；must have rained 对过去下雨作推断，overnight 指夜里。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-129">回看讲解和练习</a></p><h2 id="l130-·-情态动词-have-done" tabindex="-1">L130 · 情态动词 + have done <a class="header-anchor" href="#l130-·-情态动词-have-done" aria-label="Permalink to &quot;L130 · 情态动词 + have done {#l130-·-情态动词-have-done}&quot;">​</a></h2><p>must have rained 是推测，不能写 must had rained；情态动词后保留 have 原形。</p><p><strong>对照例句：</strong> He cannot have read the sign; it was covered.</p><p>Cannot have read 对过去是否读到标志作否定推断；it was covered 给出证据，但推断本身不是亲眼观察。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-130">回看讲解和练习</a></p><h2 id="l131-·-may-might-的时间层次" tabindex="-1">L131 · may/might 的时间层次 <a class="header-anchor" href="#l131-·-may-might-的时间层次" aria-label="Permalink to &quot;L131 · may/might 的时间层次 {#l131-·-may-might-的时间层次}&quot;">​</a></h2><p>may not arrive 表可能不到，不是“不可能到”；不要夸大确定程度。</p><p><strong>对照例句：</strong> The parcel may arrive tomorrow.</p><p>May arrive 表未来可能，arrive 保持原形；tomorrow 表时间，整句不保证包裹一定到达。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-131">回看讲解和练习</a></p>',133)])])}const u=a(s,[["render",i]]);export{g as __pageData,u as default};
